import os
from typing import List, Dict, Any
import boto3
from botocore.exceptions import ClientError

def extract_invoice_fields(file_path: str) -> Dict[str, Any]:
    """
    Extract structured fields from an invoice using AWS Textract.

    Args:
        file_path: Path to the invoice image or PDF file.

    Returns:
        Dictionary containing vendor, date, total, and line_items.
    """
    # Initialize AWS Textract client
    textract_client = boto3.client(
        'textract',
        aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY'),
        region_name=os.getenv('AWS_REGION', 'us-east-1')
    )

    # Read file bytes
    with open(file_path, 'rb') as file:
        document_bytes = file.read()

    # Call Textract AnalyzeExpense API
    try:
        response = textract_client.analyze_expense(Document={'Bytes': document_bytes})
    except ClientError as e:
        raise RuntimeError(f"AWS Textract API error: {e}")

    # Initialize result structure
    result = {
        'vendor': None,
        'date': None,
        'total': None,
        'line_items': []
    }

    # Process the first expense document (assuming single invoice per file)
    if 'ExpenseDocuments' in response and response['ExpenseDocuments']:
        expense_doc = response['ExpenseDocuments'][0]

        # Extract summary fields
        for summary_field in expense_doc.get('SummaryFields', []):
            field_type = summary_field.get('Type', {}).get('Text', '').lower()
            field_text = summary_field.get('ValueDetection', {}).get('Text')

            if field_text:
                if 'vendor' in field_type or 'name' in field_type:
                    result['vendor'] = field_text
                elif 'date' in field_type:
                    result['date'] = field_text
                elif 'total' in field_type:
                    result['total'] = field_text

        # Extract line items
        for line_item_group in expense_doc.get('LineItemGroups', []):
            for line_item in line_item_group.get('LineItems', []):
                item_data = {}
                for expense_field in line_item.get('LineItemExpenseFields', []):
                    field_type = expense_field.get('Type', {}).get('Text', '').lower()
                    field_text = expense_field.get('ValueDetection', {}).get('Text')

                    if field_text:
                        if 'description' in field_type:
                            item_data['description'] = field_text
                        elif 'quantity' in field_type:
                            item_data['quantity'] = field_text
                        elif 'unitprice' in field_type or 'price' in field_type:
                            item_data['unit_price'] = field_text
                        elif 'amount' in field_type:
                            item_data['amount'] = field_text

                if item_data:
                    result['line_items'].append(item_data)

    return result
